mapper.select:
SELECT id
FROM gamification_event
WHERE status = 'PENDING'
  AND attempt < #{maxAttempt}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE gamification_event
SET attempt = attempt + 1,
    processed_at = #{claimedAt},
    error_message = NULL,
    version = version + 1
WHERE id = #{eventId}
  AND status = 'PENDING'
  AND attempt < #{maxAttempt}
  AND version = #{expectedVersion}

UPDATE gamification_event
SET attempt = attempt + 1,
    status = CASE WHEN attempt + 1 >= #{maxAttempt} THEN 'FAILED' ELSE 'PENDING' END,
    processed_at = #{failedAt},
    error_message = #{errorMessage},
    version = version + 1
WHERE id = #{eventId}
  AND status = 'PENDING'
  AND attempt < #{maxAttempt}
  AND version = #{expectedVersion}

UPDATE user_quest_progress
SET current_count = LEAST(current_count + 1, target_count),
    completed_at = CASE
        WHEN current_count + 1 >= target_count THEN COALESCE(completed_at, #{completedAt})
        ELSE completed_at END,
    version = version + 1
WHERE user_id = #{userId}
  AND quest_code = #{questCode}
  AND period_key = #{periodKey}
  AND current_count < target_count

mapper.select:
SELECT quest_code AS questCode, period_key AS periodKey,
       target_count AS targetCount, current_count AS currentCount,
       completed_at AS completedAt
FROM user_quest_progress
WHERE user_id = #{userId}
  AND quest_code = #{questCode}
  AND period_key = #{periodKey}
FOR UPDATE

SELECT id, user_id AS userId, quest_code AS questCode, period_key AS periodKey,
       campaign_code AS campaignCode, exp_amount AS expAmount,
       ticket_amount AS ticketAmount, exp_ledger_id AS expLedgerId,
       ticket_ledger_id AS ticketLedgerId, idempotency_key AS idempotencyKey,
       policy_version AS policyVersion, create_time AS createTime
FROM quest_claim
WHERE user_id = #{userId}
  AND quest_code = #{questCode}
  AND period_key = #{periodKey}
LIMIT 1

SELECT COALESCE(SUM(CASE WHEN reward_type = 'EXP' THEN amount ELSE 0 END), 0) AS expAmount,
       COALESCE(SUM(CASE WHEN reward_type = 'TICKET' THEN amount ELSE 0 END), 0) AS ticketAmount
FROM quest_reward
WHERE quest_code = #{questCode}
  AND campaign_code = #{campaignCode}

mapper.update:
UPDATE gamification_profile
SET realm_code = #{realmCode},
    realm_changed_at = #{changedAt},
    version = version + 1
WHERE user_id = #{userId}
  AND version = #{expectedVersion}

UPDATE gamification_profile
SET ticker_opt_out = #{optOut},
    version = version + 1
WHERE user_id = #{userId}
  AND version = #{expectedVersion}
